// Normalizza nome, calcola alcolOrdine e testi per l'ordine corrente
const input = $input.first().json || {};
const body = input.body || input;
// Stable per client attempt; legacy cached pages receive a unique execution receipt.
const incomingOrderId = body.orderId;
if (incomingOrderId != null && (typeof incomingOrderId !== 'string' || !/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(incomingOrderId))) throw new Error('Invalid orderId');
const orderId = incomingOrderId || ('legacy:' + $execution.id);


const toText = (value, fallback = '') => {
  if (value === null || value === undefined) return fallback;
  if (typeof value === 'string') return value.trim();
  if (typeof value === 'number' || typeof value === 'boolean') return String(value).trim();
  return fallback;
};

const titleName = (value) => {
  const s = toText(value, 'Anonimo');
  if (!s) return 'Anonimo';
  return s.charAt(0).toUpperCase() + s.slice(1).toLowerCase();
};

const normalizeKey = (value) => toText(value).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

const nome = titleName(body.nome || body.name || body.person || body.cliente);
const orario = toText(body.orario || body.time) || new Date().toLocaleString('it-IT');
const today = new Date().toISOString().slice(0, 10);

const qty = (value) => {
  const n = Number(value || 1);
  if (!Number.isFinite(n) || n <= 0) return 1;
  return Math.max(1, Math.round(n));
};

const normalizeOrderArray = (value) => {
  if (Array.isArray(value)) return value;
  if (value && typeof value === 'object') return Object.values(value);
  if (typeof value === 'string' && value.trim()) {
    return value.split(',').map(x => ({ nome: x.trim(), quantita: 1 })).filter(x => x.nome);
  }
  return [];
};

const baseName = (item) => toText(
  item?.nome ?? item?.name ?? item?.item ?? item?.label ?? item?.title ?? item?.prodotto ?? item?.drink,
  ''
);

const baseDetail = (item) => toText(
  item?.dettaglio ?? item?.detail ?? item?.variant ?? item?.variante ?? item?.opzione ?? item?.option ?? item?.note,
  ''
);

const cleanVariantItem = (item) => {
  const src = (item && typeof item === 'object') ? item : { nome: item };
  const out = { ...src };
  let rawName = baseName(src);
  let detailRaw = baseDetail(src);
  const variant = detailRaw.replace(/^\((.*)\)$/, '$1').trim();

  // Backward-compatible fallback for old cached clients:
  // "Gin Tonic / Lemon" + "(Lemon)" -> "Gin Lemon"
  // "Vodka Tonic / Lemon" + "(Tonic)" -> "Vodka Tonic"
  if (variant && rawName.includes(' / ')) {
    const parts = rawName.split('/').map(p => p.trim()).filter(Boolean);
    const left = parts[0] || rawName;
    const alternatives = [left.split(/\s+/).pop(), ...parts.slice(1)].filter(Boolean);
    const matched = alternatives.find(a => a.toLowerCase() === variant.toLowerCase());
    if (matched) {
      const words = left.split(/\s+/).filter(Boolean);
      if (words.length > 1) {
        const prefix = words.slice(0, -1).join(' ');
        rawName = (prefix + ' ' + matched).trim();
      } else {
        rawName = matched;
      }
      detailRaw = '';
    }
  }

  // If frontend accidentally sends a container label with a detail, prefer the detail for voice.
  // This prevents umbrella items like "Digestivi" being spoken instead of the selected bottle.
  const genericContainers = new Set(['gin','rum','vodka','whisky / bourbon','whisky/bourbon','liquori','digestivi','premium','premium & digestivi']);
  if (variant && genericContainers.has(rawName.toLowerCase())) {
    rawName = variant;
    detailRaw = '';
  }

  out.nome = rawName || 'Elemento menu non riconosciuto';
  out.dettaglio = detailRaw;
  out.quantita = qty(src.quantita ?? src.quantity ?? src.qty ?? 1);
  out.alcol_grammi = Number(src.alcol_grammi ?? src.alcol ?? src.alcohol ?? 0) || 0;
  return out;
};

const speechAliases = {
  // Analcolici / base
  'cocacola': 'Coca Cola',
  'coca cola': 'Coca Cola',
  'redbull': 'Red Bull',
  'red bull': 'Red Bull',
  'the freddo pesca': 'Te freddo alla pesca',
  'acqua tonica': 'acqua tonica',
  'birra bionda': 'birra bionda',

  // Cocktail: evita parole inglesi lette male usando descrizioni italiane naturali
  'aperol spritz': 'Aperol Spritz',
  'campari spritz': 'Campari Spritz',
  'limoncello spritz': 'Limoncello Spritz',
  'il venturo spritz': 'Venturo Spritz',
  'summer spritz': 'Spritz estivo',
  'gin tonic': 'gin con acqua tonica',
  'gin lemon': 'gin lemon',
  'vodka tonic': 'vodka con acqua tonica',
  'vodka lemon': 'vodka lemon',
  'vodka coffee tonic': 'vodka con caffe e tonica',
  'cuba libre': 'Cuba Libre',
  'negroni': 'Negroni',
  'negroni sbagliato': 'Negroni Sbagliato',
  'dry martini': 'Martini dry',
  'watermelon gin tonic': 'gin tonic all anguria',
  'white dragon': 'Drago Bianco',
  'jagermeister bomb': 'Iegermaister Bomb',
  'jagermeister deer beer': 'Iegermaister con birra',

  // Premium / distillati: pronuncia italiana o descrittiva, non inglese forzato
  'mg dry gin villanova spagna': 'emme gi gin secco, Villanova Spagna',
  'larios malaga spagna': 'Larios, Malaga Spagna',
  'martin miller s london uk': 'Martin Millers, Londra Regno Unito',
  'tanqueray': 'Tancherè',
  'boigin sardegna': 'Boi Gin, Sardegna',
  'sabatini toscana': 'Sabatini, Toscana',
  'malfy limone torino': 'Malfy Limone, Torino',
  'etsu hokkaido giappone': 'Etsu, Hokkaido Giappone',
  'ginnastic match citrus blend': 'Ginnastic Match agli agrumi',
  'cabana': 'Cabana',
  'pampero anniversario': 'Pampero Anniversario',
  'monkai': 'Monkai',
  'finland': 'Finlandia',
  'wyborowa russia': 'Wyborowa, Russia',
  'jack daniel s no 7 apple': 'Jack Daniels numero sette alla mela',
  'talisker skye single malt 10 anni': 'Talisker Sky single malt, dieci anni',
  'lagavulin 16 anni': 'Lagavulin, sedici anni',
  'glengrant': 'Glen Grant',
  'limoncello menton': 'Limoncello Menton',
  'jagermeister': 'Iegermaister',
  'grand marnier': 'Gran Marnier',
  'molinari sambuca': 'Molinari Sambuca',
  'sandeman porto': 'Sandeman Porto',
  'fernet branca': 'Fernet Branca',
};


const speechName = (name, detail = '') => {
  let label = toText(name);
  if (detail) label += ' ' + toText(detail);
  const key = normalizeKey(label);
  return speechAliases[key] || speechAliases[normalizeKey(name)] || label;
};

const articleOverrides = {
  // Femminili evidenti
  'birra bionda': 'una',
  'cocacola': 'una',
  'coca cola': 'una',
  'acqua tonica': 'una',
  'redbull': 'una',
  'red bull': 'una',
  'the freddo pesca': 'un',
  'vodka': 'una',
  'finland': 'una',
  'wyborowa russia': 'una',
  'molinari sambuca': 'una',
  // Cocktail / bicchieri / liquori di solito richiesti come "un"
  'aperol spritz': 'un', 'campari spritz': 'un', 'limoncello spritz': 'un', 'il venturo spritz': 'un', 'summer spritz': 'un',
  'prosecco': 'un', 'gin tonic': 'un', 'gin lemon': 'un', 'vodka tonic': 'un', 'vodka lemon': 'un', 'vodka coffee tonic': 'un',
  'cuba libre': 'un', 'negroni': 'un', 'negroni sbagliato': 'un', 'dry martini': 'un', 'watermelon gin tonic': 'un', 'white dragon': 'un',
  'jagermeister bomb': 'un', 'jagermeister deer beer': 'un', 'jagermeister': 'un', 'limoncello menton': 'un', 'fernet branca': 'un',
  'grand marnier': 'un', 'sandeman porto': 'un',
  'mg dry gin villanova spagna': 'un', 'larios malaga spagna': 'un', 'martin miller s london uk': 'un', 'tanqueray': 'un', 'boigin sardegna': 'un', 'sabatini toscana': 'un', 'malfy limone torino': 'un', 'etsu hokkaido giappone': 'un', 'ginnastic match citrus blend': 'un',
  'cabana': 'un', 'pampero anniversario': 'un', 'monkai': 'un', 'jack daniel s no 7 apple': 'un', 'talisker skye single malt 10 anni': 'un', 'lagavulin 16 anni': 'un', 'glengrant': 'un'
};

const articleFor = (name, detail = '') => {
  const combined = normalizeKey((name || '') + ' ' + (detail || ''));
  const exact = articleOverrides[combined] || articleOverrides[normalizeKey(name)];
  if (exact) return exact;
  const spoken = normalizeKey(speechName(name, detail));
  if (articleOverrides[spoken]) return articleOverrides[spoken];
  // Conservative fallback: un before vowel sound / masculine drink names, otherwise una.
  if (/^(aperol|campari|gin|vodka|negroni|martini|prosecco|limoncello|jager|ieger|fernet|grand|talisker|lagavulin|jack|rum|whisky|dry|white|watermelon|cuba)/.test(normalizeKey(name))) return 'un';
  return 'una';
};

const ordine = normalizeOrderArray(body.ordine || body.order || body.items).map(cleanVariantItem);
if (!ordine.length) {
  ordine.push({ nome: 'Ordine ricevuto senza dettagli', dettaglio: '', quantita: 1, alcol_grammi: 0 });
}

const alcolOrdine = ordine.reduce((s, i) => s + (Number(i.alcol_grammi) || 0) * (Number(i.quantita) || 1), 0);

const ordine_str = ordine
  .map(i => {
    let s = i.quantita + 'x ' + i.nome;
    if (i.dettaglio) s += ' ' + i.dettaglio;
    return s;
  })
  .join(', ');

const qtyToSpeech = (q, itemName, detail) => {
  const n = Number(q || 1);
  if (n === 1) return articleFor(itemName, detail);
  const words = {2: 'due', 3: 'tre', 4: 'quattro', 5: 'cinque', 6: 'sei', 7: 'sette', 8: 'otto', 9: 'nove', 10: 'dieci'};
  return words[n] || String(n);
};

const ordine_voce = ordine
  .map(i => {
    const detail = i.dettaglio || '';
    return qtyToSpeech(i.quantita, i.nome, detail) + ' ' + speechName(i.nome, detail);
  })
  .join(', ');

const messaggio_voce = 'Nuovo ordine da ' + nome + '. ' + ordine_voce + '.';
return [{ json: { nome, orario, ordine, ordine_str, ordine_voce, messaggio_voce, alcolOrdine: Math.round(alcolOrdine * 10) / 10, today, orderId } }];

// Calcola BAC cumulativo leggendo le righe di oggi dal DataTable
// rows = tutti gli ordini di questa persona oggi (incluso quello appena inserito)
const rows      = $input.all().map(i => i.json);
const nome      = $('Normalize Order & Speech').item.json.nome;
const orario    = $('Normalize Order & Speech').item.json.orario;
const ordine_str = $('Normalize Order & Speech').item.json.ordine_str;

const totalAlcol = Math.round(rows.reduce((s, r) => s + (r.alcol_grammi || 0), 0) * 10) / 10;
const nOrdini    = rows.length;
const bac        = totalAlcol > 0 ? totalAlcol / (70 * 0.68) : 0;
const bacStr     = bac.toFixed(2);

const E_OK    = String.fromCodePoint(0x1F7E2);
const E_WARN  = String.fromCodePoint(0x1F7E1);
const E_OVER  = String.fromCodePoint(0x1F534);
const E_NONE  = String.fromCodePoint(0x2B1C);
const E_LIST  = String.fromCodePoint(0x1F4CB);
const E_CLOCK = String.fromCodePoint(0x1F552);
const E_DRINK = String.fromCodePoint(0x1F378);
const E_WATER = String.fromCodePoint(0x1F964);
const E_TIME  = String.fromCodePoint(0x1F550);

let bacLevel;
if      (bac === 0)  bacLevel = E_NONE;
else if (bac < 0.2)  bacLevel = E_OK;
else if (bac < 0.5)  bacLevel = E_WARN;
else                  bacLevel = E_OVER;

// Ordini precedenti = tutte le righe tranne l'ultima (quella appena inserita)
const prevOrders = rows.slice(0, -1);
const storStr = prevOrders.length > 0
  ? '\n' + E_LIST + ' Gia ordinato oggi (' + prevOrders.length + ' ordini):\n'
    + prevOrders.map(r => '  - ' + r.item + '  ' + E_CLOCK + ' ' + r.orario).join('\n')
  : '';

const bacRow = totalAlcol > 0
  ? '\n' + E_DRINK + ' BAC ~' + bacStr + ' g/L  ' + bacLevel
  : '\n' + E_WATER + ' nessun alcolico';

const messaggio = nome + ': ' + ordine_str
  + '\n' + E_TIME + ' ' + orario
  + storStr
  + bacRow;

return [{
  json: {
    nome,
    orario,
    ordine_str,
    messaggio,
    bac:        bacStr,
    bacLevel,
    totalAlcol,
    alcolOrdine: $('Normalize Order & Speech').item.json.alcolOrdine,
    nOrdini,
    today: $('Normalize Order & Speech').item.json.today
  }
}];
